"""Marca do TickerHunters: nome, textos e logo (PNG em base64 e SVG), sem depender de arquivos de imagem no repositório.

Para mudar o nome ou a descrição do produto em todo o app, altere só as constantes abaixo.
"""
NOME = "TickerHunters"
NOME_CURTO = "TickerHunters"
SLOGAN = "Caçadores de bons investimentos"
DESCRICAO = "Aprenda a investir jogando e analise ações, FIIs, ETFs, cripto e fundos em um só lugar."
COR_FUNDO = "#150F3A"
COR_MARCA = "#B6F23E"
COR_ROXO = "#5B3FD6"

LOGO_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#5B3FD6"/><stop offset="1" stop-color="#150F3A"/></linearGradient></defs><rect width="64" height="64" rx="16" fill="url(#g)"/><circle cx="32" cy="32" r="20" fill="none" stroke="#B6F23E" stroke-width="3.5"/><path d="M32 6v9M32 49v9M6 32h9M49 32h9" stroke="#B6F23E" stroke-width="3.5" stroke-linecap="round"/><rect x="22" y="34" width="5" height="9" rx="1.5" fill="#FFFFFF"/><rect x="29.5" y="28" width="5" height="15" rx="1.5" fill="#FFFFFF"/><rect x="37" y="21" width="5" height="22" rx="1.5" fill="#B6F23E"/></svg>'


def wordmark_html(tam: int = 34) -> str:
    """Logo + nome para o cabeçalho (SVG inline, nunca é cortado). `Hunters` recebe a cor de destaque (classe CSS .wm-t em)."""
    mini = LOGO_SVG.replace('id="g"', 'id="tkh"').replace('url(#g)', 'url(#tkh)')
    mini = mini.replace('<svg ', f'<svg width="{tam}" height="{tam}" aria-hidden="true" ', 1)
    return f'<div class="wm">{mini}<span class="wm-t">Ticker<em>Hunters</em></span></div>'


